arguments.code:
const fs = await import("fs");
const lines = fs.readFileSync("data.csv", "utf8").split(/\r?\n/).filter(l => l.length > 0);
const data = lines.slice(1); // drop header
const count = data.filter(l => l.split(",").length === 3).length;
console.log("data rows:", data.length, "3-field rows:", count);
await fs.promises.writeFile("count.txt", String(count) + "\n");
const back = await fs.promises.readFile("count.txt", "utf8");
console.log("count.txt contents:", JSON.stringify(back));

